// The status mark: shape + word, never colour alone. Used for run status,
// the connection badge and action feedback so every state reads the same way.
export const esc = (s) => String(s).replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);

export function mark(kind, label) {
  return `<span class="mark mark--${kind}"><span class="mark__shape" aria-hidden="true"></span>${esc(label)}</span>`;
}

// ponytail: nothing checks the API yet, so the badge says so instead of
// claiming "Connected". Pass 'live' / 'down' from health() once wiring lands.
const CONNECTION = {
  live:   ['passed', 'Connected'],
  down:   ['failed', 'API unreachable'],
  sample: ['offline', 'Not connected · sample data'],
};

export function renderBadge(state = 'sample') {
  const [kind, label] = CONNECTION[state];
  return `<span class="badge" role="status">${mark(kind, label)}</span>`;
}

