import { renderBadge, mark, esc } from './components/StatusBadge.js';

// The whole runs table. Nothing behind it.
const RUNS = [
  { id: 'r-1041', service: 'checkout', status: 'passed', started: '09:12', duration: '2m 41s' },
  { id: 'r-1040', service: 'billing',  status: 'failed', started: '08:58', duration: '1m 07s' },
  { id: 'r-1039', service: 'catalog',  status: 'passed', started: '08:31', duration: '3m 22s' },
  { id: 'r-1038', service: 'notify',   status: 'passed', started: '08:04', duration: '0m 51s' },
];

const STATUS_LABEL = { passed: 'Passed', failed: 'Failed', running: 'Running' };

function row(r) {
  return `<tr class="run run--${esc(r.status)}">
    <th scope="row" class="mono">${esc(r.id)}</th>
    <td>${esc(r.service)}</td>
    <td>${mark(r.status, STATUS_LABEL[r.status] ?? r.status)}</td>
    <td class="mono num">${esc(r.started)}</td>
    <td class="mono num">${esc(r.duration)}</td>
    <td class="act"><button type="button" class="btn btn--quiet retry" data-run="${esc(r.id)}"
      aria-label="Retry ${esc(r.id)}">Retry</button></td>
  </tr>`;
}

function summary(runs) {
  const failed = runs.filter((r) => r.status === 'failed').length;
  const total = `${runs.length} run${runs.length === 1 ? '' : 's'}`;
  return failed ? `${total}, <strong class="summary__bad">${failed} failed</strong>` : `${total}, all passed`;
}

function table(runs) {
  if (!runs.length) {
    return `<div class="empty">${mark('offline', 'No runs yet')}
      <p>Runs appear here as soon as one starts. Use New run to start one.</p></div>`;
  }
  return `<div class="scroll" role="region" aria-labelledby="runs-title" tabindex="0">
    <table>
      <thead><tr>
        <th scope="col">Run</th><th scope="col">Service</th><th scope="col">Status</th>
        <th scope="col" class="num">Started</th><th scope="col" class="num">Duration</th>
        <th scope="col"><span class="sr-only">Actions</span></th>
      </tr></thead>
      <tbody>${runs.map(row).join('')}</tbody>
    </table></div>`;
}

export function render() {
  document.querySelector('#app').innerHTML = `
    <header class="bar">
      <span class="brand">pulse</span>
      ${renderBadge()}
      <button type="button" id="new-run" class="btn btn--primary">New run</button>
    </header>
    <main class="page">
      <div class="head">
        <h1 id="runs-title">Recent runs</h1>
        <p class="summary">${summary(RUNS)}</p>
      </div>
      <p id="feedback" class="feedback" role="status" aria-live="polite"></p>
      ${table(RUNS)}
    </main>`;

  // Controls aren't wired to the API yet (separate ticket). Say so on screen
  // rather than looking like the click did something.
  const feedback = document.querySelector('#feedback');
  const notSent = (what) => {
    feedback.innerHTML = mark('offline', `${what} not sent: pulse isn't connected to the runs API yet.`);
  };
  document.querySelectorAll('.retry').forEach((b) => {
    b.addEventListener('click', () => notSent(`Retry of ${b.dataset.run}`));
  });
  document.querySelector('#new-run')
    .addEventListener('click', () => notSent('New run'));
}

render();

