/* pulse: quiet dark ops console. See DESIGN.md for the why. */
:root {
  --bg:        oklch(0.17 0.01 250);
  --surface:   oklch(0.205 0.011 250);
  --hover:     oklch(0.235 0.012 250);
  --line:      oklch(0.28 0.012 250);  /* row separators: decorative, not meaning */
  --edge:      oklch(0.55 0.015 250);  /* control borders: >=3:1 on surface */
  --ink:       oklch(0.95 0.005 250);
  --muted:     oklch(0.74 0.012 250);
  --accent:    oklch(0.80 0.12 195);   /* New run only */
  --on-accent: oklch(0.20 0.03 195);
  --ring:      oklch(0.86 0.10 195);
  --ok:        oklch(0.78 0.14 155);
  --bad:       oklch(0.72 0.17 25);
  --bad-bg:    oklch(0.235 0.035 25);
  --warn:      oklch(0.82 0.13 80);

  --sans: system-ui, -apple-system, "Segoe UI", sans-serif;
  --mono: ui-monospace, "Cascadia Mono", "SF Mono", Menlo, Consolas, monospace;
  --target: 2rem;

  color-scheme: dark;
  background: var(--bg);
  color: var(--ink);
  font: 400 1rem/1.55 var(--sans);
}
@media (pointer: coarse) { :root { --target: 2.75rem; } }

* { box-sizing: border-box; }
body { margin: 0; }

.sr-only {
  position: absolute; width: 1px; height: 1px; overflow: hidden;
  clip: rect(0 0 0 0); white-space: nowrap;
}
.mono { font-family: var(--mono); font-size: 0.875rem; }
.num { text-align: end; font-variant-numeric: tabular-nums; }

:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; border-radius: 4px; }

/* Top bar */
.bar {
  display: flex; align-items: center; gap: 1rem; flex-wrap: wrap;
  padding: 0.75rem clamp(1rem, 3vw, 2rem);
  border-block-end: 1px solid var(--line);
}
.brand { font-weight: 650; letter-spacing: -0.01em; font-size: 1.125rem; }
.badge {
  display: inline-flex; align-items: center;
  padding: 0.25rem 0.625rem; border: 1px solid var(--line); border-radius: 999px;
  font-size: 0.8125rem; color: var(--muted);
}
.bar .btn--primary { margin-inline-start: auto; }

/* Buttons: one component, two weights */
.btn {
  font: 500 0.875rem/1 var(--sans);
  min-height: var(--target); padding: 0 0.875rem;
  border-radius: 6px; border: 1px solid var(--edge);
  background: transparent; color: var(--ink); cursor: pointer;
  transition: background-color 150ms ease-out, border-color 150ms ease-out;
}
.btn:hover { background: var(--hover); }
.btn:active { background: var(--line); }
.btn--primary { background: var(--accent); border-color: var(--accent); color: var(--on-accent); font-weight: 600; }
.btn--primary:hover { background: oklch(0.85 0.11 195); }
.btn--primary:active { background: oklch(0.75 0.12 195); }
.btn--quiet { color: var(--muted); }
.btn--quiet:hover { color: var(--ink); }
.run--failed .btn--quiet { color: var(--ink); }

/* The status mark: shape + word. dot = passed, diamond = failed, ring = offline */
.mark { display: inline-flex; align-items: center; gap: 0.5rem; white-space: nowrap; }
